import heapq
def solution(lists):
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next
    h = []
    for idx, node in enumerate(lists):
        if node:
            # Python heapq tuple comparator safety needs index
            heapq.heappush(h, (node.val, idx, node))
    dummy = ListNode(0)
    curr = dummy
    while h:
        val, idx, node = heapq.heappop(h)
        curr.next = node
        curr = curr.next
        if node.next:
            heapq.heappush(h, (node.next.val, idx, node.next))
    return dummy.next
